    # Internal helpers
    # ------------------------------------------------------------------
    def _extend(self, arg: Any) -> None:
        if isinstance(arg, Mapping):
            iterable = arg.items()
        else:
            iterable = arg
        for key, value in iterable:
            self.add(key, value)

